INSERT INTO `wp_alm` (`id`, `name`, `repeaterDefault`, `repeaterType`, `pluginVersion`) VALUES (1, 'default', '<li class=\"alm-item<?php if (! has_post_thumbnail() ) { echo \' no-img\'; } ?>\">\n   <?php if ( has_post_thumbnail() ) {\n      the_post_thumbnail(\'alm-thumbnail\');\n   }?>\n   <h3><a href=\"<?php the_permalink(); ?>\"><?php the_title(); ?></a></h3>\n   <p class=\"entry-meta\">\n       <?php the_time(\"F d, Y\"); ?>\n   </p>\n   <?php the_excerpt(); ?>\n</li>\n', 'default', '5.5.4.1');
INSERT INTO `wp_comments` (`comment_ID`, `comment_post_ID`, `comment_author`, `comment_author_email`, `comment_author_url`, `comment_author_IP`, `comment_date`, `comment_date_gmt`, `comment_content`, `comment_karma`, `comment_approved`, `comment_agent`, `comment_type`, `comment_parent`, `user_id`) VALUES (1, 1, 'Một người bình luận WordPress', 'wapuu@wordpress.example', 'https://wordpress.org/', '', '2023-08-05 07:39:37', '2023-08-05 07:39:37', 'Xin chào, đây là một bình luận\nĐể bắt đầu với quản trị bình luận, chỉnh sửa hoặc xóa bình luận, vui lòng truy cập vào khu vực Bình luận trong trang quản trị.\nAvatar của người bình luận sử dụng <a href=\"https://gravatar.com\">Gravatar</a>.', 0, '1', '', 'comment', 0, 0);
