INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES (14485, 495, 'modules_3_title', 'Dấu hiệu của thoát vị đĩa đệm?');
INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES (14486, 495, '_modules_3_title', 'field_64d8a9696381d');
INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES (14487, 495, 'modules_3_text', '<ul>\r\n 	<li>Đau nhức dữ dội vùng cổ - vai - gáy, thắt lưng</li>\r\n 	<li>Đau tăng khi ngồi, nằm nghiêng, ho, hắt hơi hoặc đại tiện</li>\r\n 	<li>Tê ngứa râm ran hoặc mất cảm giác ở cánh tay, hai bên chân</li>\r\n 	<li>Yếu cơ tay, chân, cổ xoay cúi khó</li>\r\n 	<li>Giảm khả năng vận động.</li>\r\n</ul>');
