INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES (14653, 609, 'modules_2_', 'Thoát vị đĩa đệm là tình trạng nhân nhầy đĩa đệm cột sống thoát ra khỏi vị trí bình thường trong vòng sợi, chèn ép vào ống sống hay các rễ dây thần kinh gây đau cột sống. Bất kỳ đoạn cột sống nào cũng có thể bị thoát vị đĩa đệm nhưng phổ biến nhất là thoát vị đĩa đệm cột sống thắt lưng và thoát vị đĩa đệm cổ.');
