INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES (14865, 616, 'modules_6_treatment_card_1_text', '<h5><strong>Vật lý trị liệu</strong></h5>\r\nHệ thống bài tập chuyên sâu tác động vào mô cơ sâu, tăng sức bền của cơ và dây chằng, giúp trẻ cân bằng hai vai và khung xương chậu, lấy lại dáng đi chuẩn cho trẻ.');
