INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES (15124, 618, 'modules_6_treatment_card_0_video', 'https://www.youtube.com/watch?v=7P8GpKBsR-c');
