INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES (16567, 633, 'modules_5_text', 'Thoát vị đĩa đệm nếu không điều trị kịp thời hoặc tiếp cận sai cách chữa, có thể để lại nhiều biến chứng nguy hại đến sức khỏe như:\r\n<ul>\r\n 	<li>Mất khả năng vận động</li>\r\n 	<li>Rối loạn cảm giác</li>\r\n 	<li>Tổn thương thần kinh tọa</li>\r\n 	<li>Yếu cơ Bại liệt</li>\r\n 	<li>Đại tiểu tiện không tự chủ</li>\r\n</ul>');
